def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1
    bg = max(freq, key=freq.get)
    colors = sorted((n, c) for c, n in freq.items() if c != bg)
    line = max(colors)[1]
    dots = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
            if grid[r][c] not in (bg, line)]
    if not dots:
        return out
    ink = dots[0][2]
    k = len(dots)

    edges = [
        ([(0, c) for c in range(w)], (1, 0)),
        ([(h - 1, c) for c in range(w)], (-1, 0)),
        ([(r, 0) for r in range(h)], (0, 1)),
        ([(r, w - 1) for r in range(h)], (0, -1)),
    ]
    for cells, (dr, dc) in edges:
        runs = []
        run = []
        for pos in cells:
            if grid[pos[0]][pos[1]] == line:
                run.append(pos)
            elif run:
                runs.append(run)
                run = []
        if run:
            runs.append(run)
        for run in runs:
            n = len(run)
            for i in range(k):
                lo = (i * n) // k
                hi = ((i + 1) * n) // k
                if lo >= hi:
                    continue
                pos = run[lo + (hi - lo - 1) // 2]
                r, c = pos[0] + dr, pos[1] + dc
                while 0 <= r < h and 0 <= c < w:
                    value = grid[r][c]
                    if value == line:
                        break
                    if value != bg:
                        out[r][c] = 4
                        break
                    out[r][c] = ink
                    r += dr
                    c += dc
    return out
